// DIAGNOSTIC_CHECKS: 200 checks across 25 categories
export interface DiagnosticCheck {
  id: string;
  category: string;
  categoryNumber: number;
  title: string;
  description?: string;
  failCondition: string;
  mode: "FLAW" | "GAP";
  severity: "Critical" | "High" | "Medium" | "Low";
  requiresEvidence: boolean;
}

const DIAGNOSTIC_CHECKS: DiagnosticCheck[] = [
  { id: 'HERO_001', category: 'Hero Section', categoryNumber: 1, title: 'Headline is benefit-absent', failCondition: 'Headline describes what the product IS rather than what it DOES for the customer. No outcome, transformation, or result stated.', mode: 'FLAW', severity: 'Critical', requiresEvidence: true },
  { id: 'HERO_002', category: 'Hero Section', categoryNumber: 1, title: 'Headline is too vague or generic', failCondition: 'Headline contains generic phrases like "Welcome to", "Premium Quality", "The Best", "Your Journey", "Discover" with no specific claim attached.', mode: 'FLAW', severity: 'Critical', requiresEvidence: true },
  { id: 'HERO_003', category: 'Hero Section', categoryNumber: 1, title: 'Headline does not name the customer or their problem', failCondition: 'Headline makes no reference to who the product is for or what pain or desire it addresses. Reads as brand-centric rather than customer-centric.', mode: 'FLAW', severity: 'High', requiresEvidence: false },
  { id: 'HERO_004', category: 'Hero Section', categoryNumber: 1, title: 'No subheadline or supporting copy in hero', failCondition: 'No subheadline or body copy exists within the hero section to expand on the headline claim or bridge to the CTA.', mode: 'GAP', severity: 'High', requiresEvidence: false },
  { id: 'HERO_005', category: 'Hero Section', categoryNumber: 1, title: 'Hero CTA absent above the fold', failCondition: 'No clickable CTA button exists within the first viewport. Visitor must scroll to find any action to take.', mode: 'GAP', severity: 'Critical', requiresEvidence: false },
  { id: 'HERO_006', category: 'Hero Section', categoryNumber: 1, title: 'Hero CTA text is generic', failCondition: 'CTA text is one of: Shop Now, Buy Now, Click Here, Submit, Go, Enter, Learn More, Get Started — with no benefit, specificity, or outcome attached.', mode: 'FLAW', severity: 'High', requiresEvidence: true },
  { id: 'HERO_007', category: 'Hero Section', categoryNumber: 1, title: 'Hero image does not show product or outcome', failCondition: 'Hero image is abstract, decorative, or a lifestyle image with no clear product or transformation visible. Visitor cannot identify what is being sold from the image alone.', mode: 'FLAW', severity: 'High', requiresEvidence: false },
  { id: 'HERO_008', category: 'Hero Section', categoryNumber: 1, title: 'No urgency or reason to act now in hero', failCondition: 'Hero section contains no time-sensitive element — no limited offer, no scarcity signal, no deadline, no "today only" framing.', mode: 'GAP', severity: 'Medium', requiresEvidence: false },
  { id: 'HERO_009', category: 'Hero Section', categoryNumber: 1, title: 'Hero does not address primary fear or objection', failCondition: 'No risk-reversal, guarantee, or objection-handling language visible in the hero such as "No contracts", "Money-back guarantee", or "No side effects".', mode: 'GAP', severity: 'High', requiresEvidence: false },
  { id: 'HERO_010', category: 'Hero Section', categoryNumber: 1, title: 'Headline and hero image are misaligned', failCondition: 'The headline makes a claim the hero image does not visually support. Text and visual tell different stories.', mode: 'FLAW', severity: 'Medium', requiresEvidence: false },
  { id: 'HERO_011', category: 'Hero Section', categoryNumber: 1, title: 'No social proof signal visible in hero', failCondition: 'No review count, star rating, customer count, or press mention is visible within or immediately below the hero section.', mode: 'GAP', severity: 'High', requiresEvidence: false },
  { id: 'HERO_012', category: 'Hero Section', categoryNumber: 1, title: 'Hero section is cluttered with competing focal points', failCondition: 'Hero contains more than one primary CTA, multiple competing headlines, or excessive visual elements that dilute attention from the main message.', mode: 'FLAW', severity: 'Medium', requiresEvidence: false },
  { id: 'TRUST_001', category: 'Trust & Credibility', categoryNumber: 2, title: 'No money-back guarantee mentioned', failCondition: 'No guarantee of any kind (satisfaction, money-back, results-based) is visible anywhere on the homepage or hero area.', mode: 'GAP', severity: 'Critical', requiresEvidence: false },
  { id: 'TRUST_002', category: 'Trust & Credibility', categoryNumber: 2, title: 'Guarantee exists but is buried', failCondition: 'A guarantee is mentioned but only in the footer, FAQ, or a separate page — not visible in the hero or near CTAs where purchase decisions happen.', mode: 'FLAW', severity: 'High', requiresEvidence: false },
  { id: 'TRUST_003', category: 'Trust & Credibility', categoryNumber: 2, title: 'No named or attributed testimonials', failCondition: 'No testimonials exist, or testimonials present have no name, photo, or identifying information attached. Anonymous quotes have near-zero trust value.', mode: 'GAP', severity: 'Critical', requiresEvidence: false },
  { id: 'TRUST_004', category: 'Trust & Credibility', categoryNumber: 2, title: 'Testimonials are vague and unspecific', failCondition: 'Testimonials present contain no specific result, timeframe, or measurable outcome. Generic praise like "Great product!" or "Highly recommend" with no detail.', mode: 'FLAW', severity: 'High', requiresEvidence: true },
  { id: 'TRUST_005', category: 'Trust & Credibility', categoryNumber: 2, title: 'No photo or video testimonials', failCondition: 'All testimonials are text-only with no accompanying customer photo or video. Visual proof significantly increases credibility.', mode: 'GAP', severity: 'High', requiresEvidence: false },
  { id: 'TRUST_006', category: 'Trust & Credibility', categoryNumber: 2, title: 'No press or media mentions visible', failCondition: 'No "As Seen In" section, no media logos, no press quote anywhere on the homepage.', mode: 'GAP', severity: 'Medium', requiresEvidence: false },
  { id: 'TRUST_007', category: 'Trust & Credibility', categoryNumber: 2, title: 'No certifications or third-party validations', failCondition: 'No certifications, lab testing badges, industry awards, or third-party validation signals present for a product category where these are expected such as supplements, skincare, or food.', mode: 'GAP', severity: 'Medium', requiresEvidence: false },
  { id: 'TRUST_008', category: 'Trust & Credibility', categoryNumber: 2, title: 'No founder or brand story visible', failCondition: 'No mention of who founded the brand, why it was created, or the human behind the product. Faceless brands convert lower in trust-dependent categories.', mode: 'GAP', severity: 'Medium', requiresEvidence: false },
  { id: 'TRUST_009', category: 'Trust & Credibility', categoryNumber: 2, title: 'Ingredient or material transparency absent', failCondition: 'For product categories where ingredient quality is a purchase factor such as supplements, skincare, food, or cleaning products, no ingredient sourcing, quality claim, or transparency signal is present.', mode: 'GAP', severity: 'High', requiresEvidence: false },
  { id: 'TRUST_010', category: 'Trust & Credibility', categoryNumber: 2, title: 'Trust badges absent near CTA', failCondition: 'No security badges, payment logos, SSL signals, or safety indicators visible near the primary CTA or purchase button.', mode: 'GAP', severity: 'High', requiresEvidence: false },
  { id: 'TRUST_011', category: 'Trust & Credibility', categoryNumber: 2, title: 'Review count is low or not displayed', failCondition: 'Review count shown is under 10, or the total review count is hidden and only a star rating is shown. Low visible review counts reduce rather than build trust.', mode: 'FLAW', severity: 'High', requiresEvidence: true },
  { id: 'TRUST_012', category: 'Trust & Credibility', categoryNumber: 2, title: 'No before/after or transformation proof', failCondition: 'For transformation-based products such as skincare, supplements, fitness, or weight loss, no before/after imagery, results timeline, or measurable outcome proof exists.', mode: 'GAP', severity: 'Medium', requiresEvidence: false },
  { id: 'TRUST_013', category: 'Trust & Credibility', categoryNumber: 2, title: 'Claims made without evidence', failCondition: 'Page makes specific performance claims such as "clinically proven", "dermatologist approved", or "increases energy by 40%" with no linked study, certification, or evidence source.', mode: 'FLAW', severity: 'Critical', requiresEvidence: true },
  { id: 'TRUST_014', category: 'Trust & Credibility', categoryNumber: 2, title: 'No customer count or social volume signal', failCondition: 'No "Join 10,000+ customers", "Trusted by X people", or equivalent social volume claim anywhere on the page.', mode: 'GAP', severity: 'Medium', requiresEvidence: false },
  { id: 'CTA_001', category: 'CTA & Conversion', categoryNumber: 3, title: 'Only one CTA exists on the entire page', failCondition: 'The primary CTA appears only once. High-converting pages repeat the CTA at logical decision points — after proof, after features, after testimonials.', mode: 'FLAW', severity: 'High', requiresEvidence: false },
  { id: 'CTA_002', category: 'CTA & Conversion', categoryNumber: 3, title: 'CTA button has low visual contrast', failCondition: 'CTA button color does not contrast sufficiently with the surrounding background. Button does not immediately stand out as the primary action.', mode: 'FLAW', severity: 'Critical', requiresEvidence: false },
  { id: 'CTA_003', category: 'CTA & Conversion', categoryNumber: 3, title: 'No CTA after testimonials section', failCondition: 'Testimonials section exists but is not followed by a CTA. This is a missed conversion moment — social proof is highest-intent real estate.', mode: 'GAP', severity: 'High', requiresEvidence: false },
  { id: 'CTA_004', category: 'CTA & Conversion', categoryNumber: 3, title: 'No CTA after pricing section', failCondition: 'Pricing is displayed but no CTA immediately follows. Visitor sees price and has nowhere obvious to go next.', mode: 'GAP', severity: 'High', requiresEvidence: false },
  { id: 'CTA_005', category: 'CTA & Conversion', categoryNumber: 3, title: 'No sticky or persistent CTA', failCondition: 'No sticky header, floating button, or persistent CTA element follows the visitor as they scroll. Long pages with no persistent CTA lose momentum.', mode: 'GAP', severity: 'Medium', requiresEvidence: false },
  { id: 'CTA_006', category: 'CTA & Conversion', categoryNumber: 3, title: 'Urgency language absent from CTA', failCondition: 'CTA button or surrounding copy contains no urgency signal — no "Today Only", "Limited Stock", "Ends Sunday", or equivalent.', mode: 'GAP', severity: 'Medium', requiresEvidence: false },
  { id: 'CTA_007', category: 'CTA & Conversion', categoryNumber: 3, title: 'No secondary CTA for non-ready visitors', failCondition: 'Page offers only a buy or purchase CTA with no lower-commitment option such as a quiz, free sample, email signup, or learn more for visitors not ready to purchase.', mode: 'GAP', severity: 'Medium', requiresEvidence: false },
  { id: 'CTA_008', category: 'CTA & Conversion', categoryNumber: 3, title: 'Form fields create excessive friction', failCondition: 'Any visible lead capture or checkout form requests more than 3 fields before delivering value. Each additional field reduces completion rate.', mode: 'FLAW', severity: 'High', requiresEvidence: false },
  { id: 'CTA_009', category: 'CTA & Conversion', categoryNumber: 3, title: 'CTA does not match visitor awareness stage', failCondition: 'CTA assumes purchase-ready intent such as Buy Now on a page where the visitor has not yet been given sufficient reason to trust or understand the product. No warm-up sequence before the hard sell.', mode: 'FLAW', severity: 'High', requiresEvidence: false },
  { id: 'CTA_010', category: 'CTA & Conversion', categoryNumber: 3, title: 'No free trial, sample, or risk-free entry point', failCondition: 'For products over $30, no low-risk entry point exists — no sample, trial size, starter kit, or free shipping on first order to reduce purchase barrier.', mode: 'GAP', severity: 'Medium', requiresEvidence: false },
  { id: 'CTA_011', category: 'CTA & Conversion', categoryNumber: 3, title: 'CTA copy does not indicate what happens next', failCondition: 'CTA text gives no indication of what clicking will do. Visitor does not know what they are committing to.', mode: 'FLAW', severity: 'Medium', requiresEvidence: true },
  { id: 'CTA_012', category: 'CTA & Conversion', categoryNumber: 3, title: 'Mobile CTA is too small or hard to tap', failCondition: 'Based on visual analysis, CTA button appears too small for comfortable mobile tapping or is positioned too close to other interactive elements.', mode: 'FLAW', severity: 'Critical', requiresEvidence: false },
  { id: 'MSG_001', category: 'Messaging & Clarity', categoryNumber: 4, title: 'Value proposition not clear within 5 seconds', failCondition: 'A first-time visitor cannot determine within 5 seconds what the product does, who it is for, and why it is different. The above-fold content does not answer these three questions.', mode: 'FLAW', severity: 'Critical', requiresEvidence: false },
  { id: 'MSG_002', category: 'Messaging & Clarity', categoryNumber: 4, title: 'Features listed without corresponding benefits', failCondition: 'Product descriptions list technical features or ingredients without translating them into customer outcomes. "Contains Vitamin C" instead of "Brightens skin in 2 weeks."', mode: 'FLAW', severity: 'High', requiresEvidence: true },
  { id: 'MSG_003', category: 'Messaging & Clarity', categoryNumber: 4, title: 'No differentiation from competitors stated', failCondition: 'No claim, comparison, or statement explains why this product is different or better than alternatives. Visitor has no reason to choose this over a competitor.', mode: 'GAP', severity: 'High', requiresEvidence: false },
  { id: 'MSG_004', category: 'Messaging & Clarity', categoryNumber: 4, title: 'Excessive jargon or technical language', failCondition: 'Page uses industry terminology, scientific names, or technical language without plain-language explanation in a context where the audience is general consumers.', mode: 'FLAW', severity: 'Medium', requiresEvidence: true },
  { id: 'MSG_005', category: 'Messaging & Clarity', categoryNumber: 4, title: 'Copy is brand-centric rather than customer-centric', failCondition: 'Majority of copy uses "We", "Our", "Us" framing rather than "You" and "Your" framing. Brand talks about itself rather than the customer\'s situation.', mode: 'FLAW', severity: 'High', requiresEvidence: false },
  { id: 'MSG_006', category: 'Messaging & Clarity', categoryNumber: 4, title: 'No problem articulation before solution', failCondition: 'Page jumps directly to product features without first acknowledging the customer\'s pain point or desire. Visitors who do not feel understood bounce.', mode: 'FLAW', severity: 'High', requiresEvidence: false },
  { id: 'MSG_007', category: 'Messaging & Clarity', categoryNumber: 4, title: 'Page is not skimmable', failCondition: 'Page uses dense paragraphs with no subheadings, bullet points, or visual breaks. 80% of visitors skim — if key messages are not visible at a glance they are missed.', mode: 'FLAW', severity: 'Medium', requiresEvidence: false },
  { id: 'MSG_008', category: 'Messaging & Clarity', categoryNumber: 4, title: 'Pricing absent or hidden', failCondition: 'No pricing is visible on the homepage or landing page. Hiding price increases perceived risk and forces visitors to click through unnecessarily before knowing if the product fits their budget.', mode: 'FLAW', severity: 'High', requiresEvidence: false },
  { id: 'MSG_009', category: 'Messaging & Clarity', categoryNumber: 4, title: 'No objection handling copy present', failCondition: 'Page makes no attempt to address common purchase objections such as "Does it really work?", "Is it safe?", "What if it does not work for me?", or "How long until I see results?"', mode: 'GAP', severity: 'High', requiresEvidence: false },
  { id: 'MSG_010', category: 'Messaging & Clarity', categoryNumber: 4, title: 'Reading level too high for target audience', failCondition: 'Copy uses unnecessarily complex sentence structures or vocabulary for a consumer product audience. Optimal reading level for e-commerce is Grade 6-8.', mode: 'FLAW', severity: 'Low', requiresEvidence: false },
  { id: 'SOCIAL_001', category: 'Social Proof', categoryNumber: 5, title: 'No reviews or testimonials anywhere on page', failCondition: 'Zero customer reviews, testimonials, or user-generated content detected anywhere on the homepage.', mode: 'GAP', severity: 'Critical', requiresEvidence: false },
  { id: 'SOCIAL_002', category: 'Social Proof', categoryNumber: 5, title: 'Star rating shown without review count', failCondition: 'A star rating is displayed but the number of reviews is hidden or not shown. A star rating without a review count is unverifiable and carries little trust weight.', mode: 'FLAW', severity: 'High', requiresEvidence: false },
  { id: 'SOCIAL_003', category: 'Social Proof', categoryNumber: 5, title: 'No video testimonials', failCondition: 'All social proof is text-based. Video testimonials convert significantly higher than text — no video proof exists.', mode: 'GAP', severity: 'Medium', requiresEvidence: false },
  { id: 'SOCIAL_004', category: 'Social Proof', categoryNumber: 5, title: 'Testimonials not specific to outcomes', failCondition: 'Testimonials present do not mention specific results, timeframes, or measurable improvements. Outcome-specific testimonials convert dramatically better than general praise.', mode: 'FLAW', severity: 'High', requiresEvidence: true },
  { id: 'SOCIAL_005', category: 'Social Proof', categoryNumber: 5, title: 'No UGC or real customer imagery', failCondition: 'No user-generated content, customer photos, or real-world product usage imagery present. Stock photography used exclusively.', mode: 'GAP', severity: 'Medium', requiresEvidence: false },
  { id: 'SOCIAL_006', category: 'Social Proof', categoryNumber: 5, title: 'No case studies or detailed success stories', failCondition: 'No long-form customer story, case study, or detailed transformation narrative exists anywhere on the site.', mode: 'GAP', severity: 'Medium', requiresEvidence: false },
  { id: 'SOCIAL_007', category: 'Social Proof', categoryNumber: 5, title: 'Social proof not segmented by customer type', failCondition: 'All testimonials are generic with no segmentation by use case, customer type, or specific concern. Different buyer personas cannot find proof relevant to their situation.', mode: 'GAP', severity: 'Low', requiresEvidence: false },
  { id: 'SOCIAL_008', category: 'Social Proof', categoryNumber: 5, title: 'No third-party review platform integration', failCondition: 'No integration with third-party review platforms such as Trustpilot, Google Reviews, Yotpo, or Judge.me that provide independently verified social proof.', mode: 'GAP', severity: 'Medium', requiresEvidence: false },
  { id: 'SOCIAL_009', category: 'Social Proof', categoryNumber: 5, title: 'No influencer or celebrity proof', failCondition: 'For lifestyle or consumer brands where influencer credibility is a category norm, no influencer mentions, partnerships, or celebrity endorsements are referenced.', mode: 'GAP', severity: 'Low', requiresEvidence: false },
  { id: 'SOCIAL_010', category: 'Social Proof', categoryNumber: 5, title: 'No community size or follower count signal', failCondition: 'No reference to community size, social following, or active customer community that signals brand legitimacy and scale.', mode: 'GAP', severity: 'Low', requiresEvidence: false },
  { id: 'SEO_001', category: 'SEO & Metadata', categoryNumber: 6, title: 'Page title missing or generic', failCondition: 'Title tag is absent, matches the domain name only, or contains no target keyword or value proposition.', mode: 'FLAW', severity: 'High', requiresEvidence: true },
  { id: 'SEO_002', category: 'SEO & Metadata', categoryNumber: 6, title: 'Meta description missing or auto-generated', failCondition: 'Meta description is absent or is clearly auto-generated — truncated product description, repeating the title, or over 160 characters with no call to action.', mode: 'FLAW', severity: 'High', requiresEvidence: true },
  { id: 'SEO_003', category: 'SEO & Metadata', categoryNumber: 6, title: 'H1 absent or multiple H1s present', failCondition: 'Page has no H1 tag, or has more than one H1 tag. Both conditions damage SEO and indicate structural content problems.', mode: 'FLAW', severity: 'High', requiresEvidence: false },
  { id: 'SEO_004', category: 'SEO & Metadata', categoryNumber: 6, title: 'H1 contains no target keyword', failCondition: 'The H1 present does not contain a keyword a potential customer would use to find this type of product.', mode: 'FLAW', severity: 'Medium', requiresEvidence: true },
  { id: 'SEO_005', category: 'SEO & Metadata', categoryNumber: 6, title: 'Images have no alt text', failCondition: 'Product or hero images detected have empty or missing alt attributes. Both an SEO and accessibility failure.', mode: 'FLAW', severity: 'Medium', requiresEvidence: false },
  { id: 'SEO_006', category: 'SEO & Metadata', categoryNumber: 6, title: 'No structured data signals detected', failCondition: 'No schema markup signals detected for Product, Review, Organization, or BreadcrumbList. Structured data enables rich search results and increases click-through rate.', mode: 'GAP', severity: 'Medium', requiresEvidence: false },
  { id: 'SEO_007', category: 'SEO & Metadata', categoryNumber: 6, title: 'Meta description has no call to action', failCondition: 'Meta description exists but reads as a passive description with no action verb or reason to click over competing results.', mode: 'FLAW', severity: 'Low', requiresEvidence: true },
  { id: 'SEO_008', category: 'SEO & Metadata', categoryNumber: 6, title: 'Page load speed signals suggest poor performance', failCondition: 'Visual analysis or page weight signals suggest the page has excessive image sizes, render-blocking elements, or other performance issues likely causing slow load times. Every 1 second delay reduces conversion 7%.', mode: 'FLAW', severity: 'High', requiresEvidence: false },
  { id: 'NAV_001', category: 'Navigation & UX', categoryNumber: 7, title: 'Navigation has too many items', failCondition: 'Primary navigation contains more than 7 items at the top level. Excessive navigation options split visitor attention and reduce click-through on priority pages.', mode: 'FLAW', severity: 'Medium', requiresEvidence: false },
  { id: 'NAV_002', category: 'Navigation & UX', categoryNumber: 7, title: 'No search functionality on multi-product site', failCondition: 'Site appears to have more than 10 products but no search bar is visible in the navigation. Visitors who cannot find products quickly leave.', mode: 'GAP', severity: 'Medium', requiresEvidence: false },
  { id: 'NAV_003', category: 'Navigation & UX', categoryNumber: 7, title: 'Footer missing key pages', failCondition: 'Footer does not include links to Contact, About, Shipping Policy, Return Policy, and Privacy Policy. Missing footer links reduce trust and create legal exposure.', mode: 'FLAW', severity: 'Medium', requiresEvidence: false },
  { id: 'NAV_004', category: 'Navigation & UX', categoryNumber: 7, title: 'No breadcrumb navigation on product pages', failCondition: 'Product or category pages detected with no breadcrumb trail. Breadcrumbs improve navigation and SEO on multi-level sites.', mode: 'GAP', severity: 'Low', requiresEvidence: false },
  { id: 'NAV_005', category: 'Navigation & UX', categoryNumber: 7, title: 'Mobile navigation not clearly accessible', failCondition: 'Based on visual analysis, mobile hamburger menu or navigation trigger is not clearly visible or accessible in the mobile viewport.', mode: 'FLAW', severity: 'High', requiresEvidence: false },
  { id: 'NAV_006', category: 'Navigation & UX', categoryNumber: 7, title: 'No clear path from homepage to purchase', failCondition: 'The conversion path from homepage to product to cart to checkout is not obvious. Visitor cannot intuitively navigate to purchase within 2 clicks from the homepage.', mode: 'FLAW', severity: 'Critical', requiresEvidence: false },
  { id: 'NAV_007', category: 'Navigation & UX', categoryNumber: 7, title: 'Collection pages lack filtering', failCondition: 'For sites with more than 15 products, no filtering or sorting options detected on collection pages. Visitors cannot narrow products to their specific need.', mode: 'GAP', severity: 'Medium', requiresEvidence: false },
  { id: 'NAV_008', category: 'Navigation & UX', categoryNumber: 7, title: 'No live chat or immediate support option', failCondition: 'No live chat widget, chatbot, or immediately visible support contact option present. For high-consideration purchases, real-time support significantly increases conversion.', mode: 'GAP', severity: 'Low', requiresEvidence: false },
  { id: 'PSY_001', category: 'Psychology & Persuasion', categoryNumber: 8, title: 'No loss aversion framing used', failCondition: 'Copy frames only positive gains with no mention of what the visitor risks losing by not acting — missed results, continued struggle, or the cost of inaction.', mode: 'GAP', severity: 'Medium', requiresEvidence: false },
  { id: 'PSY_002', category: 'Psychology & Persuasion', categoryNumber: 8, title: 'No authority markers present', failCondition: 'No expert endorsements, professional credentials, years in business, patents, research backing, or authority signals establish the brand as credible in its category.', mode: 'GAP', severity: 'High', requiresEvidence: false },
  { id: 'PSY_003', category: 'Psychology & Persuasion', categoryNumber: 8, title: 'Scarcity signals absent', failCondition: 'No stock level indicators, limited edition signals, or production quantity references create urgency through scarcity.', mode: 'GAP', severity: 'Medium', requiresEvidence: false },
  { id: 'PSY_004', category: 'Psychology & Persuasion', categoryNumber: 8, title: 'Scarcity or urgency signals appear fake', failCondition: 'Countdown timers, "Only 3 left" claims, or urgency language appear non-dynamic or implausible. Fake urgency destroys trust when detected.', mode: 'FLAW', severity: 'High', requiresEvidence: true },
  { id: 'PSY_005', category: 'Psychology & Persuasion', categoryNumber: 8, title: 'No reciprocity mechanism present', failCondition: 'No free value offered before the ask — no free guide, quiz, sample, educational content, or tool that gives before taking.', mode: 'GAP', severity: 'Medium', requiresEvidence: false },
  { id: 'PSY_006', category: 'Psychology & Persuasion', categoryNumber: 8, title: 'Pain points not amplified before solution', failCondition: 'Copy moves to solution too quickly without dwelling on the customer\'s current painful situation. Visitors need to feel understood before they trust a solution.', mode: 'FLAW', severity: 'High', requiresEvidence: false },
  { id: 'PSY_007', category: 'Psychology & Persuasion', categoryNumber: 8, title: 'Aspiration framing absent', failCondition: 'Copy focuses only on product features or problem relief with no aspirational vision of the customer\'s better future state.', mode: 'GAP', severity: 'Medium', requiresEvidence: false },
  { id: 'PSY_008', category: 'Psychology & Persuasion', categoryNumber: 8, title: 'No micro-commitment or consistency trigger', failCondition: 'No quiz, assessment, preference selector, or micro-commitment step gets visitors to invest small effort before the purchase ask, increasing follow-through likelihood.', mode: 'GAP', severity: 'Low', requiresEvidence: false },
  { id: 'PSY_009', category: 'Psychology & Persuasion', categoryNumber: 8, title: 'Social consensus language absent', failCondition: 'No "Join thousands of customers", "Most popular choice", "Best seller" or equivalent consensus language that normalizes the purchase decision.', mode: 'GAP', severity: 'Medium', requiresEvidence: false },
  { id: 'PSY_010', category: 'Psychology & Persuasion', categoryNumber: 8, title: 'Pricing not anchored against reference point', failCondition: 'Price is presented alone with no comparison to a higher-priced alternative, the cost of the problem, or a crossed-out original price that makes the current price feel like a deal.', mode: 'GAP', severity: 'Medium', requiresEvidence: false },
  { id: 'PAGE_001', category: 'Page & Content Gaps', categoryNumber: 9, title: 'No dedicated reviews or testimonials page', failCondition: 'Site has no standalone reviews, testimonials, or results page. Buyers actively research reviews before purchasing — a dedicated page captures this intent and provides SEO value.', mode: 'GAP', severity: 'High', requiresEvidence: false },
  { id: 'PAGE_002', category: 'Page & Content Gaps', categoryNumber: 9, title: 'No "Why Us" or comparison page', failCondition: 'No page exists that directly compares this brand to competitors or answers why a visitor should choose this brand over alternatives. This is one of the highest-intent pages a buyer visits before converting.', mode: 'GAP', severity: 'High', requiresEvidence: false },
  { id: 'PAGE_003', category: 'Page & Content Gaps', categoryNumber: 9, title: 'No FAQ page', failCondition: 'No FAQ page detected. FAQs handle objections at scale, reduce support load, and capture long-tail SEO traffic from pre-purchase questions.', mode: 'GAP', severity: 'Medium', requiresEvidence: false },
  { id: 'PAGE_004', category: 'Page & Content Gaps', categoryNumber: 9, title: 'No how-it-works or ingredients page', failCondition: 'For products where mechanism matters such as supplements, skincare, tech, or services, no dedicated page explains how the product works or what is in it. Informed buyers convert better.', mode: 'GAP', severity: 'High', requiresEvidence: false },
  { id: 'PAGE_005', category: 'Page & Content Gaps', categoryNumber: 9, title: 'No founder or brand story page', failCondition: 'No About page or founder story exists. Story-driven brands command higher loyalty and price premiums — the absence of a human story is a missed trust opportunity.', mode: 'GAP', severity: 'Medium', requiresEvidence: false },
  { id: 'PAGE_006', category: 'Page & Content Gaps', categoryNumber: 9, title: 'No blog or educational content', failCondition: 'No blog, journal, or educational content hub exists. Educational content builds organic search traffic, establishes authority, and warms cold visitors before they reach product pages.', mode: 'GAP', severity: 'Medium', requiresEvidence: false },
  { id: 'PAGE_007', category: 'Page & Content Gaps', categoryNumber: 9, title: 'No results or before/after gallery page', failCondition: 'For transformation products, no gallery, results page, or visual proof hub exists. A dedicated results page can be the single highest-converting page on a DTC site.', mode: 'GAP', severity: 'Medium', requiresEvidence: false },
  { id: 'PAGE_008', category: 'Page & Content Gaps', categoryNumber: 9, title: 'No quiz or product finder tool', failCondition: 'For brands with multiple products or SKUs, no quiz or recommendation tool exists to guide visitors to the right product. Quizzes also capture email and segment leads.', mode: 'GAP', severity: 'Medium', requiresEvidence: false },
  { id: 'PAGE_009', category: 'Page & Content Gaps', categoryNumber: 9, title: 'No bundle or multi-product page', failCondition: 'No bundle, kit, or multi-product offering detected. Bundles increase average order value and simplify the decision for visitors who want a complete solution.', mode: 'GAP', severity: 'Medium', requiresEvidence: false },
  { id: 'PAGE_010', category: 'Page & Content Gaps', categoryNumber: 9, title: 'No loyalty or rewards program page', failCondition: 'No loyalty program, rewards scheme, or referral program exists or is referenced. Retention programs dramatically reduce customer acquisition costs over time.', mode: 'GAP', severity: 'Low', requiresEvidence: false },
  { id: 'PAGE_011', category: 'Page & Content Gaps', categoryNumber: 9, title: 'No community or user group page', failCondition: 'No community hub, Facebook group link, forum, or customer community exists. Community increases retention, generates UGC, and reduces churn.', mode: 'GAP', severity: 'Low', requiresEvidence: false },
  { id: 'PAGE_012', category: 'Page & Content Gaps', categoryNumber: 9, title: 'No press or media page', failCondition: 'No dedicated press page or media kit exists. For brands seeking PR and partnerships, a press page signals professionalism and is essential for media outreach.', mode: 'GAP', severity: 'Low', requiresEvidence: false },
  { id: 'OFFER_001', category: 'Offer & Pricing', categoryNumber: 10, title: 'Pricing not clearly displayed', failCondition: 'Product pricing is absent from the homepage or requires multiple clicks to find. Hidden pricing increases bounce rate on price-sensitive purchases.', mode: 'FLAW', severity: 'High', requiresEvidence: false },
  { id: 'OFFER_002', category: 'Offer & Pricing', categoryNumber: 10, title: 'No subscription or recurring purchase option', failCondition: 'For consumable products such as supplements, skincare, coffee, or cleaning products, no subscription or auto-ship option exists. Subscriptions dramatically increase lifetime value.', mode: 'GAP', severity: 'Medium', requiresEvidence: false },
  { id: 'OFFER_003', category: 'Offer & Pricing', categoryNumber: 10, title: 'No bundle discount or volume pricing', failCondition: 'No multi-unit discount, buy-more-save-more pricing, or bundle offer exists. Bundle pricing increases AOV and reduces per-unit cost perception.', mode: 'GAP', severity: 'Medium', requiresEvidence: false },
  { id: 'OFFER_004', category: 'Offer & Pricing', categoryNumber: 10, title: 'Free shipping threshold not visible', failCondition: 'Shipping cost or free shipping threshold is not visible until checkout. Unexpected shipping costs are the number one cause of cart abandonment.', mode: 'FLAW', severity: 'High', requiresEvidence: false },
  { id: 'OFFER_005', category: 'Offer & Pricing', categoryNumber: 10, title: 'No payment plan or BNPL option', failCondition: 'For products over $50, no buy-now-pay-later option such as Afterpay, Klarna, or Shop Pay Installments exists. BNPL can increase conversion 20-30% on higher-ticket items.', mode: 'GAP', severity: 'Medium', requiresEvidence: false },
  { id: 'OFFER_006', category: 'Offer & Pricing', categoryNumber: 10, title: 'Offer value not framed against problem cost', failCondition: 'Price presented with no comparison to the cost of the alternative such as competitor price, cost of inaction, or professional service cost. Price feels higher when not anchored.', mode: 'GAP', severity: 'Medium', requiresEvidence: false },
  { id: 'OFFER_007', category: 'Offer & Pricing', categoryNumber: 10, title: 'No introductory or first-order incentive', failCondition: 'No first-order discount, welcome offer, free gift with purchase, or new customer incentive exists to reduce the friction of the first purchase.', mode: 'GAP', severity: 'High', requiresEvidence: false },
  { id: 'OFFER_008', category: 'Offer & Pricing', categoryNumber: 10, title: 'Sale or discount not clearly communicated', failCondition: 'A sale or promotional pricing exists but the original price, savings amount, or discount percentage is not clearly displayed alongside the sale price.', mode: 'FLAW', severity: 'Medium', requiresEvidence: false },
  { id: 'EMAIL_001', category: 'Email & Retention', categoryNumber: 11, title: 'No email capture mechanism on homepage', failCondition: 'No email signup form, popup, flyout, or lead capture of any kind detected. Email list is the highest-ROI owned channel — its absence means all traffic is lost if visitors do not purchase immediately.', mode: 'GAP', severity: 'Critical', requiresEvidence: false },
  { id: 'EMAIL_002', category: 'Email & Retention', categoryNumber: 11, title: 'Email capture has no incentive', failCondition: 'An email signup exists but offers no reason to subscribe — no discount, free guide, early access, or value exchange. Unincentivized email capture converts at a fraction of incentivized capture.', mode: 'FLAW', severity: 'High', requiresEvidence: false },
  { id: 'EMAIL_003', category: 'Email & Retention', categoryNumber: 11, title: 'No exit intent or scroll-triggered capture', failCondition: 'No exit intent popup, scroll-triggered offer, or timed popup exists to capture visitors who are about to leave without purchasing or subscribing.', mode: 'GAP', severity: 'Medium', requiresEvidence: false },
  { id: 'EMAIL_004', category: 'Email & Retention', categoryNumber: 11, title: 'No SMS capture option', failCondition: 'No SMS or text marketing signup exists. SMS has 98% open rates versus 20% for email — for e-commerce brands, SMS capture is a significant revenue lever.', mode: 'GAP', severity: 'Low', requiresEvidence: false },
  { id: 'EMAIL_005', category: 'Email & Retention', categoryNumber: 11, title: 'No loyalty or referral program mentioned', failCondition: 'No referral program, loyalty points, or reward for repeat purchases is mentioned anywhere on the site. Referral programs can reduce CAC by 30-50%.', mode: 'GAP', severity: 'Medium', requiresEvidence: false },
  { id: 'EMAIL_006', category: 'Email & Retention', categoryNumber: 11, title: 'No post-purchase upsell or cross-sell path', failCondition: 'No signals of a post-purchase flow — no frequently bought together, no order bump, no thank-you page offer. Post-purchase is the highest-conversion moment and it is unused.', mode: 'GAP', severity: 'Medium', requiresEvidence: false },
  { id: 'PROD_001', category: 'Product Page', categoryNumber: 12, title: 'Product description leads with features not benefits', failCondition: 'Product page description opens with a list of features, ingredients, or specifications before establishing what the product does for the customer.', mode: 'FLAW', severity: 'High', requiresEvidence: false },
  { id: 'PROD_002', category: 'Product Page', categoryNumber: 12, title: 'No usage instructions or how-to information', failCondition: 'Product page has no usage instructions, application guide, or how-to section. Uncertainty about how to use a product is a significant purchase barrier.', mode: 'GAP', severity: 'Medium', requiresEvidence: false },
  { id: 'PROD_003', category: 'Product Page', categoryNumber: 12, title: 'No results timeline or expectation setting', failCondition: 'For products where results take time such as supplements, skincare, or fitness, no timeline is given for when results can be expected. Uncertainty about outcomes reduces purchase confidence.', mode: 'GAP', severity: 'High', requiresEvidence: false },
  { id: 'PROD_004', category: 'Product Page', categoryNumber: 12, title: 'No comparison table against alternatives', failCondition: 'No comparison table contrasting this product against competitors or the brand\'s own product range exists on the product page.', mode: 'GAP', severity: 'Medium', requiresEvidence: false },
  { id: 'PROD_005', category: 'Product Page', categoryNumber: 12, title: 'No complementary product recommendations', failCondition: 'No "pairs well with", "complete the routine", or "frequently bought together" section exists on the product page. Cross-sell recommendations increase AOV significantly.', mode: 'GAP', severity: 'Medium', requiresEvidence: false },
  { id: 'PROD_006', category: 'Product Page', categoryNumber: 12, title: 'Reviews not integrated on product page', failCondition: 'Product page has no reviews section or review integration. 93% of consumers say reviews impact purchase decisions — their absence at the point of purchase is critical.', mode: 'GAP', severity: 'Critical', requiresEvidence: false },
  { id: 'PROD_007', category: 'Product Page', categoryNumber: 12, title: 'No product FAQ on product page', failCondition: 'No FAQ section on the product page to handle common objections at the moment of highest purchase intent.', mode: 'GAP', severity: 'Medium', requiresEvidence: false },
  { id: 'PROD_008', category: 'Product Page', categoryNumber: 12, title: 'Insufficient product imagery', failCondition: 'Product page has fewer than 3 product images, no lifestyle imagery, no ingredient or detail shots, or no video view. Insufficient imagery is a top reason for purchase abandonment on product pages.', mode: 'FLAW', severity: 'High', requiresEvidence: false },
  { id: 'MOBILE_001', category: 'Mobile Experience', categoryNumber: 13, title: 'Hero content not visible above fold on mobile', failCondition: 'Based on visual analysis, the hero headline, subheadline, or primary CTA is not visible within the first mobile viewport. Visitor must scroll before understanding what the page offers.', mode: 'FLAW', severity: 'Critical', requiresEvidence: false },
  { id: 'MOBILE_002', category: 'Mobile Experience', categoryNumber: 13, title: 'Font sizes too small on mobile', failCondition: 'Body copy appears below 16px on mobile viewport. Text requires pinch-zoom to read comfortably, creating immediate friction.', mode: 'FLAW', severity: 'High', requiresEvidence: false },
  { id: 'MOBILE_003', category: 'Mobile Experience', categoryNumber: 13, title: 'CTA not visible above fold on mobile', failCondition: 'Primary CTA button does not appear within the first mobile viewport. Mobile visitors who do not see an action within the first screen have significantly higher bounce rates.', mode: 'FLAW', severity: 'Critical', requiresEvidence: false },
  { id: 'MOBILE_004', category: 'Mobile Experience', categoryNumber: 13, title: 'Intrusive popup blocks mobile content', failCondition: 'A popup, interstitial, or overlay appears immediately on mobile that covers the main content before the visitor has engaged. Google penalizes this with ranking demotions.', mode: 'FLAW', severity: 'High', requiresEvidence: false },
  { id: 'MOBILE_005', category: 'Mobile Experience', categoryNumber: 13, title: 'Touch targets too small or too close together', failCondition: 'Buttons, links, or interactive elements appear smaller than 44x44px or are positioned within 8px of adjacent interactive elements on mobile. Creates misclick frustration and abandonment.', mode: 'FLAW', severity: 'High', requiresEvidence: false },
  { id: 'MOBILE_006', category: 'Mobile Experience', categoryNumber: 13, title: 'Images not optimized for mobile viewport', failCondition: 'Hero or product images appear cropped, distorted, or oversized on mobile. Desktop-sized images served to mobile create slow load times and visual breakage.', mode: 'FLAW', severity: 'Medium', requiresEvidence: false },
  { id: 'MOBILE_007', category: 'Mobile Experience', categoryNumber: 13, title: 'No social proof visible above fold on mobile', failCondition: 'On mobile, social proof signals such as star rating, review count, or customer count are not visible within the first viewport. Mobile visitors need trust signals immediately.', mode: 'GAP', severity: 'Medium', requiresEvidence: false },
  { id: 'MOBILE_008', category: 'Mobile Experience', categoryNumber: 13, title: 'Horizontal scrolling present on mobile', failCondition: 'Visual analysis indicates content extends beyond the mobile viewport width causing unwanted horizontal scrolling. This is a fundamental mobile UX failure.', mode: 'FLAW', severity: 'High', requiresEvidence: false },
  { id: 'CHECK_001', category: 'Checkout & Purchase Friction', categoryNumber: 14, title: 'No guest checkout option visible or implied', failCondition: 'No indication that guest checkout is available. Forcing account creation before purchase is the single highest-impact cause of checkout abandonment — 34% of shoppers abandon when required to create an account.', mode: 'GAP', severity: 'Critical', requiresEvidence: false },
  { id: 'CHECK_002', category: 'Checkout & Purchase Friction', categoryNumber: 14, title: 'Checkout step count is too high', failCondition: 'Checkout flow appears to require more than 3 steps before purchase completion. Each additional checkout step reduces completion rate by approximately 10%.', mode: 'FLAW', severity: 'High', requiresEvidence: false },
  { id: 'CHECK_003', category: 'Checkout & Purchase Friction', categoryNumber: 14, title: 'Payment method diversity insufficient', failCondition: 'No signals of alternative payment methods beyond credit card — no PayPal, Apple Pay, Google Pay, Shop Pay, or equivalent. 56% of online shoppers expect their preferred payment method to be available.', mode: 'GAP', severity: 'High', requiresEvidence: false },
  { id: 'CHECK_004', category: 'Checkout & Purchase Friction', categoryNumber: 14, title: 'No BNPL option at checkout', failCondition: 'For products over $40, no buy-now-pay-later option such as Afterpay, Klarna, or Shop Pay Installments is referenced near pricing or at checkout. BNPL increases conversion 20-30% on higher-ticket items.', mode: 'GAP', severity: 'Medium', requiresEvidence: false },
  { id: 'CHECK_005', category: 'Checkout & Purchase Friction', categoryNumber: 14, title: 'Security reassurance absent at point of purchase', failCondition: 'No SSL badge, secure checkout indicator, or security reassurance visible at or near the checkout or cart stage. Visitors entering payment details need explicit security confirmation.', mode: 'GAP', severity: 'Critical', requiresEvidence: false },
  { id: 'CHECK_006', category: 'Checkout & Purchase Friction', categoryNumber: 14, title: 'Shipping cost not revealed until late in checkout', failCondition: 'Shipping cost or free shipping threshold is not communicated before the cart or checkout stage. Unexpected shipping costs revealed late in checkout are the number one cause of cart abandonment globally.', mode: 'FLAW', severity: 'Critical', requiresEvidence: false },
  { id: 'CHECK_007', category: 'Checkout & Purchase Friction', categoryNumber: 14, title: 'No order summary visible during checkout', failCondition: 'Checkout flow does not display a persistent order summary showing items, quantities, and total. Visitors lose confidence when they cannot verify what they are paying for at the moment of payment.', mode: 'FLAW', severity: 'High', requiresEvidence: false },
  { id: 'CHECK_008', category: 'Checkout & Purchase Friction', categoryNumber: 14, title: 'No progress indicator in checkout flow', failCondition: 'Checkout flow shows no step indicator or progress bar. Visitors who cannot see how many steps remain abandon at higher rates due to uncertainty about commitment required.', mode: 'GAP', severity: 'Medium', requiresEvidence: false },
  { id: 'SPEED_001', category: 'Page Speed & Technical', categoryNumber: 15, title: 'Page weight suggests slow load time', failCondition: 'Page source or visual analysis indicates excessive page weight — large uncompressed images, numerous third-party scripts, or render-blocking resources. Every 1 second of load delay reduces conversions by 7%.', mode: 'FLAW', severity: 'Critical', requiresEvidence: false },
  { id: 'SPEED_002', category: 'Page Speed & Technical', categoryNumber: 15, title: 'Images not served in modern format', failCondition: 'Images detected are served as JPEG or PNG rather than WebP or AVIF. Modern image formats reduce file size 25-35% with equivalent visual quality, directly improving load speed.', mode: 'FLAW', severity: 'Medium', requiresEvidence: false },
  { id: 'SPEED_003', category: 'Page Speed & Technical', categoryNumber: 15, title: 'Render-blocking scripts in page head', failCondition: 'Page source indicates JavaScript or CSS files loaded synchronously in the document head that block page rendering. Visitors see a blank or partial page while these load.', mode: 'FLAW', severity: 'High', requiresEvidence: false },
  { id: 'SPEED_004', category: 'Page Speed & Technical', categoryNumber: 15, title: 'Excessive third-party scripts detected', failCondition: 'Page loads more than 5 third-party scripts such as analytics, pixels, chat widgets, review apps, and marketing tools. Each third-party script adds latency and creates potential single points of failure.', mode: 'FLAW', severity: 'Medium', requiresEvidence: false },
  { id: 'SPEED_005', category: 'Page Speed & Technical', categoryNumber: 15, title: 'No lazy loading on below-fold images', failCondition: 'Images below the fold appear to load immediately rather than lazily. Eager-loading all images increases initial page load time unnecessarily, delaying time-to-interactive for above-fold content.', mode: 'FLAW', severity: 'Medium', requiresEvidence: false },
  { id: 'SPEED_006', category: 'Page Speed & Technical', categoryNumber: 15, title: 'No CDN signals detected', failCondition: 'No content delivery network signals detected in page headers or asset URLs. Without a CDN, visitors geographically distant from the hosting server experience significantly slower load times.', mode: 'GAP', severity: 'Medium', requiresEvidence: false },
  { id: 'FLOW_001', category: 'Emotional Sequence & Page Flow', categoryNumber: 16, title: 'Page opens with navigation or admin content before value', failCondition: 'The first content a visitor encounters is navigation, announcement bars, cookie notices, or promotional banners rather than a compelling headline or value statement. Attention is the scarcest resource — the first thing seen must earn the next second of attention.', mode: 'FLAW', severity: 'High', requiresEvidence: false },
  { id: 'FLOW_002', category: 'Emotional Sequence & Page Flow', categoryNumber: 16, title: 'Trust signals appear before desire is established', failCondition: 'Reviews, certifications, and guarantees appear in the page flow before the product benefit or transformation has been communicated. Trust signals are most powerful after the visitor wants the outcome — placing them before creates a sequence where the visitor has not yet decided they want what is being offered.', mode: 'FLAW', severity: 'High', requiresEvidence: false },
  { id: 'FLOW_003', category: 'Emotional Sequence & Page Flow', categoryNumber: 16, title: 'Page has no logical narrative arc', failCondition: 'Page sections appear in random or illogical order with no sense of a guided journey. High-converting pages follow a consistent emotional arc: Problem Acknowledgment, Solution Introduction, Proof, Objection Handling, CTA. The page should tell a story that ends in purchase.', mode: 'FLAW', severity: 'High', requiresEvidence: false },
  { id: 'FLOW_004', category: 'Emotional Sequence & Page Flow', categoryNumber: 16, title: 'CTA appears before sufficient value communicated', failCondition: 'Primary CTA appears very early in the page flow before the visitor has been given meaningful reason to trust or want the product. Premature CTAs signal desperation and ignore the visitor\'s need to be convinced before being asked.', mode: 'FLAW', severity: 'High', requiresEvidence: false },
  { id: 'FLOW_005', category: 'Emotional Sequence & Page Flow', categoryNumber: 16, title: 'No visual breathing room between sections', failCondition: 'Sections are visually compressed with insufficient whitespace between them. Cognitive overload from dense layouts reduces reading comprehension and increases the likelihood of abandonment.', mode: 'FLAW', severity: 'Medium', requiresEvidence: false },
  { id: 'FLOW_006', category: 'Emotional Sequence & Page Flow', categoryNumber: 16, title: 'Page ends weakly with no final CTA', failCondition: 'The page ends with footer links, legal text, or passive content with no final compelling CTA. Visitors who scroll to the bottom are highly engaged — failing to capture them at this moment is a significant missed conversion opportunity.', mode: 'FLAW', severity: 'High', requiresEvidence: false },
  { id: 'DIFF_001', category: 'Competitive Differentiation', categoryNumber: 17, title: 'No unique mechanism stated', failCondition: 'No specific proprietary method, ingredient, process, technology, or approach is named that only this brand uses or does. The unique mechanism is the most powerful differentiation tool in direct response marketing — without it the product is a commodity.', mode: 'GAP', severity: 'Critical', requiresEvidence: false },
  { id: 'DIFF_002', category: 'Competitive Differentiation', categoryNumber: 17, title: 'No direct or indirect competitor comparison', failCondition: 'No comparison to alternatives — no "unlike other products", no comparison table, no "why we are different" framing that positions this product against the broader competitive landscape.', mode: 'GAP', severity: 'High', requiresEvidence: false },
  { id: 'DIFF_003', category: 'Competitive Differentiation', categoryNumber: 17, title: 'No category leadership claim', failCondition: 'No claim of being first, best, most popular, most reviewed, fastest, or any superlative that establishes a category position. Category leaders convert better — even a specific leadership claim creates conversion lift.', mode: 'GAP', severity: 'Medium', requiresEvidence: false },
  { id: 'DIFF_004', category: 'Competitive Differentiation', categoryNumber: 17, title: 'No specific named target customer', failCondition: 'The product is positioned for everyone which means it resonates with no one specifically. No named customer persona, specific life situation, or defined audience is called out. Specific audience targeting dramatically outperforms generic positioning.', mode: 'FLAW', severity: 'High', requiresEvidence: false },
  { id: 'DIFF_005', category: 'Competitive Differentiation', categoryNumber: 17, title: 'Origin or sourcing story absent', failCondition: 'For products where ingredient origin or manufacturing process is a quality signal such as supplements, skincare, food, or textiles, no sourcing story, country of origin, or manufacturing standard is referenced.', mode: 'GAP', severity: 'Medium', requiresEvidence: false },
  { id: 'DIFF_006', category: 'Competitive Differentiation', categoryNumber: 17, title: 'No response to dominant category objection', failCondition: 'Every product category has a dominant objection such as "Does it really work?", "Is it safe?", "Will it work for me?", or "Why is it so expensive?". No content on the page directly addresses the single most common objection a potential buyer in this category would have.', mode: 'GAP', severity: 'High', requiresEvidence: false },
  { id: 'SPEC_001', category: 'Specificity & Claim Quality', categoryNumber: 18, title: 'Results claims contain no timeframe', failCondition: 'Any results claim present such as "helps with energy", "improves skin", or "increases focus" contains no specific timeframe for when results can be expected. Vague claims are mentally discounted by skeptical buyers.', mode: 'FLAW', severity: 'High', requiresEvidence: true },
  { id: 'SPEC_002', category: 'Specificity & Claim Quality', categoryNumber: 18, title: 'Testimonials contain no measurable outcome', failCondition: 'Testimonials present contain no specific number, timeframe, or measurable result. Specific testimonials increase believability and conversion — vague ones are ignored.', mode: 'FLAW', severity: 'High', requiresEvidence: true },
  { id: 'SPEC_003', category: 'Specificity & Claim Quality', categoryNumber: 18, title: 'Guarantee terms are not specific', failCondition: 'A guarantee is mentioned but its terms are vague — no specific number of days, no explanation of the refund process, no clarity on what qualifies. Specific guarantee terms convert better than vague assurances.', mode: 'FLAW', severity: 'Medium', requiresEvidence: true },
  { id: 'SPEC_004', category: 'Specificity & Claim Quality', categoryNumber: 18, title: 'CTA does not specify what happens after clicking', failCondition: 'CTA text or surrounding microcopy does not tell the visitor exactly what happens when they click. Uncertainty about the next step reduces click-through rate.', mode: 'FLAW', severity: 'Medium', requiresEvidence: true },
  { id: 'SPEC_005', category: 'Specificity & Claim Quality', categoryNumber: 18, title: 'Ingredient or feature claims not quantified', failCondition: 'For products where dosage, concentration, or quantity matters such as supplements or skincare actives, ingredient amounts or feature specifications are absent or vague. Quantified claims convert better than unquantified ones.', mode: 'FLAW', severity: 'Medium', requiresEvidence: true },
  { id: 'SPEC_006', category: 'Specificity & Claim Quality', categoryNumber: 18, title: 'Social proof numbers are suspiciously round', failCondition: 'Customer counts or review numbers are suspiciously round such as "10,000 customers" or "500 reviews" suggesting they are estimates rather than real figures. Specific numbers are perceived as more credible because they appear real and counted.', mode: 'FLAW', severity: 'Medium', requiresEvidence: true },
  { id: 'RET_001', category: 'Return Visitor & Retention', categoryNumber: 19, title: 'No personalization for return visitors', failCondition: 'Site shows identical content to first-time and return visitors with no personalization signals — no welcome back message, no recently viewed products, no cart persistence, no loyalty points display. Return visitors convert at 3-5x the rate of new visitors and deserve a differentiated experience.', mode: 'GAP', severity: 'Medium', requiresEvidence: false },
  { id: 'RET_002', category: 'Return Visitor & Retention', categoryNumber: 19, title: 'No abandoned cart recovery mechanism', failCondition: 'No signals of abandoned cart recovery — no exit-intent cart reminder, no persistent cart that survives session end. 70% of carts are abandoned — recovery sequences typically recapture 5-15% of lost revenue.', mode: 'GAP', severity: 'High', requiresEvidence: false },
  { id: 'RET_003', category: 'Return Visitor & Retention', categoryNumber: 19, title: 'No win-back mechanism for lapsed customers', failCondition: 'No signals of a win-back or re-engagement mechanism for customers who have purchased before but not returned. Win-back sequences are among the highest-ROI email flows for e-commerce brands.', mode: 'GAP', severity: 'Low', requiresEvidence: false },
  { id: 'RET_004', category: 'Return Visitor & Retention', categoryNumber: 19, title: 'Account benefits not visible to returning customers', failCondition: 'For returning logged-in customers, no visible account benefits, order history, loyalty points balance, or personalized recommendations are surfaced. The logged-in experience is identical to the logged-out experience, eliminating the incentive to create an account.', mode: 'GAP', severity: 'Low', requiresEvidence: false },
  { id: 'ACCESS_001', category: 'Accessibility & Inclusion', categoryNumber: 20, title: 'Text contrast ratio insufficient', failCondition: 'Based on visual analysis, text color against its background does not meet minimum contrast standards. Low contrast excludes visitors with visual impairments and is a conversion failure for all visitors in bright ambient light conditions.', mode: 'FLAW', severity: 'High', requiresEvidence: false },
  { id: 'ACCESS_002', category: 'Accessibility & Inclusion', categoryNumber: 20, title: 'No alt text on product or hero images', failCondition: 'Key images have no descriptive alt text. This excludes screen reader users, fails visitors when images do not load, and misses SEO keyword opportunities.', mode: 'FLAW', severity: 'Medium', requiresEvidence: false },
  { id: 'ACCESS_003', category: 'Accessibility & Inclusion', categoryNumber: 20, title: 'Forms have no visible labels', failCondition: 'Input fields in any form use placeholder text as the only label with no persistent visible label above or beside the field. Placeholder-only labels disappear when the user begins typing, creating confusion particularly for users with cognitive impairments.', mode: 'FLAW', severity: 'Medium', requiresEvidence: false },
  { id: 'ACCESS_004', category: 'Accessibility & Inclusion', categoryNumber: 20, title: 'Color used as only means of conveying information', failCondition: 'Any information on the page is communicated through color alone with no text or icon backup — for example required form fields shown only in red, or sale prices distinguished only by color change. 8% of men have color vision deficiency — color-only communication excludes them entirely.', mode: 'FLAW', severity: 'Medium', requiresEvidence: false },

  // ── Universal & Cross-Vertical (21) ──────────────────────────────────────
  { id: 'UNIV_001', category: 'Universal & Cross-Vertical', categoryNumber: 21, title: 'No video content present', failCondition: 'No product demo video, explainer video, testimonial video, or any video content detected on the page. Video increases time on site and conversion rates across all site types.', mode: 'GAP', severity: 'Medium', requiresEvidence: false },
  { id: 'UNIV_002', category: 'Universal & Cross-Vertical', categoryNumber: 21, title: 'No exit-intent mechanism', failCondition: 'No exit-intent popup, overlay, or mechanism exists to capture visitors before they leave without converting. Exit-intent triggers retain 10-15% of otherwise-lost visitors.', mode: 'GAP', severity: 'Medium', requiresEvidence: false },
  { id: 'UNIV_003', category: 'Universal & Cross-Vertical', categoryNumber: 21, title: 'Visitor cannot orient within 3 seconds above the fold', failCondition: 'The above-fold content does not simultaneously communicate what the site offers, who it is for, and what action to take next. A visitor landing cold cannot answer all three questions within 3 seconds of arrival.', mode: 'FLAW', severity: 'Critical', requiresEvidence: false },
  { id: 'UNIV_004', category: 'Universal & Cross-Vertical', categoryNumber: 21, title: 'No real-time support channel visible', failCondition: 'No live chat widget, chatbot, or immediately visible real-time support option is present. For high-consideration or complex purchases, the absence of accessible real-time help drives abandonment at the decision stage.', mode: 'GAP', severity: 'Low', requiresEvidence: false },
  { id: 'UNIV_005', category: 'Universal & Cross-Vertical', categoryNumber: 21, title: 'Visual hierarchy does not guide the eye', failCondition: 'The page lacks a clear visual hierarchy — no dominant focal point, inconsistent heading sizes, or multiple visual elements competing at equal weight. Without hierarchy, visitors do not know where to look and attention fragments.', mode: 'FLAW', severity: 'High', requiresEvidence: false },
  { id: 'UNIV_006', category: 'Universal & Cross-Vertical', categoryNumber: 21, title: 'No international or currency signals for global audiences', failCondition: 'No currency selector, international shipping notice, or localization signal is present for visitors outside the primary market. For brands with global traffic, absence of localization signals creates purchase friction for non-domestic visitors.', mode: 'GAP', severity: 'Low', requiresEvidence: false },
  { id: 'UNIV_007', category: 'Universal & Cross-Vertical', categoryNumber: 21, title: 'Cookie consent banner obstructs page content', failCondition: 'A cookie consent banner or GDPR notice blocks significant page content, overlays the hero, or forces interaction before the visitor can see the primary value proposition. Cookie notices must not obstruct the conversion experience.', mode: 'FLAW', severity: 'High', requiresEvidence: false },
  { id: 'UNIV_008', category: 'Universal & Cross-Vertical', categoryNumber: 21, title: 'No site search on multi-page site', failCondition: 'Site appears to have more than 10 pages or products but no site search functionality is present in the navigation or header. Visitors who cannot locate content quickly abandon rather than browse.', mode: 'GAP', severity: 'Medium', requiresEvidence: false },
  { id: 'UNIV_009', category: 'Universal & Cross-Vertical', categoryNumber: 21, title: 'Contact information not visible without scrolling', failCondition: 'No phone number, email address, or direct contact link is visible above the fold or in a persistent header. Visitors who cannot quickly verify a human is reachable lose trust, particularly for first-time purchases.', mode: 'GAP', severity: 'High', requiresEvidence: false },
  { id: 'UNIV_010', category: 'Universal & Cross-Vertical', categoryNumber: 21, title: '404 page not optimized for visitor recovery', failCondition: 'No evidence of a custom 404 page that offers a search bar, navigation to high-value pages, or a clear return path. Standard 404 errors with no recovery mechanism are full exit events that eliminate conversion opportunity.', mode: 'GAP', severity: 'Medium', requiresEvidence: false },
  { id: 'UNIV_011', category: 'Universal & Cross-Vertical', categoryNumber: 21, title: 'Social media links navigate away without opening a new tab', failCondition: 'Social media icons in header or footer open in the same browser tab, sending visitors away from the site with no return path. External links must open in a new tab to preserve the active conversion session.', mode: 'FLAW', severity: 'Medium', requiresEvidence: false },
  { id: 'UNIV_012', category: 'Universal & Cross-Vertical', categoryNumber: 21, title: 'No printable or downloadable version of key content', failCondition: 'For sites with complex information such as service packages, menus, or product specifications that buyers review offline, no print-friendly page or downloadable PDF is available. Offline-ready content extends the sales cycle to include offline decision-makers.', mode: 'GAP', severity: 'Low', requiresEvidence: false },

  // ── SaaS-Specific (22) ────────────────────────────────────────────────────
  { id: 'SAAS_001', category: 'SaaS-Specific', categoryNumber: 22, title: 'Signup or onboarding flow requires too many steps', failCondition: 'The signup, registration, or onboarding flow requires more than 3 fields or steps before delivering value. SaaS products that gate value behind lengthy signups see sharply higher activation abandonment.', mode: 'FLAW', severity: 'Critical', requiresEvidence: false },
  { id: 'SAAS_002', category: 'SaaS-Specific', categoryNumber: 22, title: 'Free trial terms not clearly stated near CTA', failCondition: 'A free trial is offered but the duration, credit card requirement, and what occurs at trial end are not clearly stated adjacent to the signup CTA. Ambiguous trial terms reduce signup rates and generate post-trial refund disputes.', mode: 'GAP', severity: 'Critical', requiresEvidence: false },
  { id: 'SAAS_003', category: 'SaaS-Specific', categoryNumber: 22, title: 'No integration or compatibility signals', failCondition: 'No mention of compatible platforms, integrations, or supported technology stack. SaaS buyers must confirm a tool works within their existing environment before evaluating it further — absence of this information stalls the evaluation.', mode: 'GAP', severity: 'High', requiresEvidence: false },
  { id: 'SAAS_004', category: 'SaaS-Specific', categoryNumber: 22, title: 'Pricing tier differences not clearly differentiated', failCondition: 'Pricing tiers exist but the meaningful differences between them are not immediately clear. Visitors cannot determine which tier fits their situation without extended cross-referencing of feature tables.', mode: 'FLAW', severity: 'High', requiresEvidence: false },
  { id: 'SAAS_005', category: 'SaaS-Specific', categoryNumber: 22, title: 'No product screenshot or interface preview above fold', failCondition: 'No product screenshot, UI preview, or demo video is visible in the hero section or above the fold. SaaS visitors need to see the product interface before they will invest time in a trial or demo request.', mode: 'GAP', severity: 'High', requiresEvidence: false },
  { id: 'SAAS_006', category: 'SaaS-Specific', categoryNumber: 22, title: 'No audience segmentation or "who this is for" signal', failCondition: 'The product is presented without a clear named audience — no customer type, use case, or persona is identified. Visitors self-select out when they cannot confirm the product is built for their specific role or context.', mode: 'GAP', severity: 'High', requiresEvidence: false },

  // ── E-commerce Specific (23) ──────────────────────────────────────────────
  { id: 'ECOM_001', category: 'E-commerce Specific', categoryNumber: 23, title: 'No size guide or fit information for sized products', failCondition: 'For products with sizing such as apparel, footwear, or accessories, no size guide, measurement chart, or fit recommendation is visible on the product page. Sizing uncertainty is one of the primary drivers of both purchase abandonment and return events.', mode: 'GAP', severity: 'High', requiresEvidence: false },
  { id: 'ECOM_002', category: 'E-commerce Specific', categoryNumber: 23, title: 'Return policy not visible near add-to-cart', failCondition: 'Return policy is buried in the footer or a separate page with no summary visible near the add-to-cart button or pricing. Return policy visibility near the purchase decision directly correlates with purchase confidence on product pages.', mode: 'GAP', severity: 'Critical', requiresEvidence: false },
  { id: 'ECOM_003', category: 'E-commerce Specific', categoryNumber: 23, title: 'No stock level or inventory urgency signal', failCondition: 'No low-stock indicator, inventory count, or real-inventory scarcity signal is present on product pages. Stock-based urgency increases purchase rate without requiring discount promotions.', mode: 'GAP', severity: 'Medium', requiresEvidence: false },
  { id: 'ECOM_004', category: 'E-commerce Specific', categoryNumber: 23, title: 'No gift wrapping or gifting option', failCondition: 'No gift wrapping, gift message, or gifting-oriented option is visible on product or cart pages. Gifting options increase average order value and unlock a second purchase segment — buyers purchasing for others.', mode: 'GAP', severity: 'Low', requiresEvidence: false },
  { id: 'ECOM_005', category: 'E-commerce Specific', categoryNumber: 23, title: 'Shipping timeframe not communicated', failCondition: 'No estimated delivery date, dispatch timeline, or shipping timeframe is visible on the product page or near the add-to-cart button. Delivery uncertainty is a primary abandonment cause when purchase timing matters to the buyer.', mode: 'GAP', severity: 'Critical', requiresEvidence: false },
  { id: 'ECOM_006', category: 'E-commerce Specific', categoryNumber: 23, title: 'No product comparison feature for similar SKUs', failCondition: 'For sites with multiple similar products or variants, no comparison feature or side-by-side view exists. Shoppers who cannot compare products on-site go to competitor sites to make the comparison and often do not return.', mode: 'GAP', severity: 'Medium', requiresEvidence: false },

  // ── Agency & Service (24) ─────────────────────────────────────────────────
  { id: 'SERV_001', category: 'Agency & Service', categoryNumber: 24, title: 'No process or how-it-works explanation', failCondition: 'The engagement process — from initial contact through project delivery — is not explained anywhere on the site. Service buyers need to understand what working together looks like before they will commit to an inquiry or discovery call.', mode: 'GAP', severity: 'Critical', requiresEvidence: false },
  { id: 'SERV_002', category: 'Agency & Service', categoryNumber: 24, title: 'Case studies present but lack measurable outcomes', failCondition: 'Case studies or portfolio examples exist but contain no specific metrics, percentage improvements, revenue figures, or quantified client outcomes. Vague case studies are perceived as less credible than ones with specific numbers.', mode: 'FLAW', severity: 'High', requiresEvidence: true },
  { id: 'SERV_003', category: 'Agency & Service', categoryNumber: 24, title: 'No response time or inquiry turnaround signal', failCondition: 'No indication of how quickly inquiries are responded to — no "reply within 24 hours", "same-day response", or equivalent commitment. For service businesses, response speed is a key trust and vendor-selection factor.', mode: 'GAP', severity: 'High', requiresEvidence: false },
  { id: 'SERV_004', category: 'Agency & Service', categoryNumber: 24, title: 'No minimum engagement or pricing range indicated', failCondition: 'No pricing range, minimum project size, or engagement starting point is communicated anywhere on the site. The absence of any pricing signal forces potential clients to invest discovery time only to find budget misalignment.', mode: 'GAP', severity: 'High', requiresEvidence: false },
  { id: 'SERV_005', category: 'Agency & Service', categoryNumber: 24, title: 'Team credentials or expertise not visible', failCondition: 'No team page, named individuals, professional credentials, years of experience, or relevant expertise signals are present. For service businesses, buyers are fundamentally buying the people — teams that are invisible reduce conversion.', mode: 'GAP', severity: 'High', requiresEvidence: false },
  { id: 'SERV_006', category: 'Agency & Service', categoryNumber: 24, title: 'No discovery call or consultation CTA above fold', failCondition: 'The primary conversion action for a service business — a discovery call, consultation booking, or intake form — is not visible in the hero section or above the fold. The most important action the site needs visitors to take is buried below the scroll threshold.', mode: 'GAP', severity: 'Critical', requiresEvidence: false },

  // ── Conversion Path Expansion (25) ───────────────────────────────────────
  { id: 'CONV_001', category: 'Conversion Path Expansion', categoryNumber: 25, title: 'No free sample, demo, or trial entry point', failCondition: 'For higher-consideration purchases, no free sample, product demo, or trial option exists to let prospects experience value before committing to a full purchase. Risk-free first interactions significantly increase downstream conversion rates.', mode: 'GAP', severity: 'High', requiresEvidence: false },
  { id: 'CONV_002', category: 'Conversion Path Expansion', categoryNumber: 25, title: 'No upsell or cross-sell path at key conversion moments', failCondition: 'No upsell offer, order bump, or cross-sell recommendation appears at key conversion moments — cart, checkout, or post-purchase confirmation. These touchpoints are the highest-ROI moments for revenue expansion with zero additional acquisition cost.', mode: 'GAP', severity: 'Medium', requiresEvidence: false },
  { id: 'CONV_003', category: 'Conversion Path Expansion', categoryNumber: 25, title: 'No referral or affiliate program', failCondition: 'No referral program, affiliate structure, or refer-a-friend incentive exists or is referenced. Referral programs convert existing customers into a low-cost acquisition channel and produce new buyers with higher lifetime value than cold traffic.', mode: 'GAP', severity: 'Low', requiresEvidence: false },
  { id: 'CONV_004', category: 'Conversion Path Expansion', categoryNumber: 25, title: 'Cancellation or return process not proactively addressed', failCondition: 'No content proactively addresses what happens if a customer wants to cancel a subscription or return a product. Buyers who cannot find this information before purchasing perceive higher commitment risk and convert at lower rates.', mode: 'GAP', severity: 'High', requiresEvidence: false },
];

export default DIAGNOSTIC_CHECKS;
